using System;
using System.IO;
using System.IO.Compression;
using System.Xml;
using System.Text;
using System.Globalization;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using System.Web.Script.Serialization;

// Dependency-free OOXML I/O. Office remains responsible for formula calculation.
public static class SentimentXlsx {
 const string Ns="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
 static readonly CultureInfo Inv=CultureInfo.InvariantCulture;
 static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=32000000};}
 static XmlDocument Read(ZipArchive z,string path){var e=z.GetEntry(path);if(e==null)throw new InvalidDataException("Missing XLSX part: "+path);var d=new XmlDocument();d.XmlResolver=null;using(var s=e.Open())using(var r=XmlReader.Create(s,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null}))d.Load(r);return d;}
 static void Save(ZipArchive z,string path,XmlDocument d){var old=z.GetEntry(path);if(old!=null)old.Delete();using(var s=z.CreateEntry(path,CompressionLevel.Optimal).Open())using(var w=XmlWriter.Create(s,new XmlWriterSettings{Encoding=new UTF8Encoding(false)}))d.Save(w);}
 static XmlNodeList Nodes(XmlNode n,string xpath){return n.SelectNodes(xpath);}
 static XmlElement Child(XmlNode n,string name){return (XmlElement)n.SelectSingleNode("*[local-name()='"+name+"']");}
 static XmlElement Add(XmlNode n,string name){var e=n.OwnerDocument.CreateElement(name,Ns);n.AppendChild(e);return e;}
 static List<string> Sheets(ZipArchive z){var b=Read(z,"xl/workbook.xml");var rel=Read(z,"xl/_rels/workbook.xml.rels");var map=new Dictionary<string,string>();foreach(XmlElement e in rel.DocumentElement.ChildNodes){if(e.GetAttribute("TargetMode")=="External")continue;var p=new Uri(new Uri("http://xlsx/xl/workbook.xml"),e.GetAttribute("Target")).AbsolutePath.TrimStart('/');map[e.GetAttribute("Id")]=p;}var list=new List<string>();foreach(XmlElement s in Nodes(b,"//*[local-name()='sheet']")){string id=s.GetAttribute("id","http://schemas.openxmlformats.org/officeDocument/2006/relationships");list.Add(map[id]);}return list;}
 static string Decode(string s){return Regex.Replace(s,"_x([0-9a-fA-F]{4})_",m=>((char)int.Parse(m.Groups[1].Value,NumberStyles.HexNumber,Inv)).ToString());}
 static string Encode(string s){s=Regex.Replace(s,"_x[0-9a-fA-F]{4}_",m=>"_x005F_"+m.Value.Substring(1));return Regex.Replace(s,"[\\x00-\\x08\\x0B\\x0C\\x0D\\x0E-\\x1F]",m=>"_x"+((int)m.Value[0]).ToString("X4",Inv)+"_");}
 static object DateValue(object value){DateTime date;if(value is string&&DateTime.TryParseExact((string)value,"yyyy-MM-dd",Inv,DateTimeStyles.None,out date))return date.ToOADate();return value;}
 static string Text(XmlNode n){var b=new StringBuilder();foreach(XmlNode t in Nodes(n,"*[local-name()='t']|*[local-name()='r']/*[local-name()='t']"))b.Append(t.InnerText);return Decode(b.ToString());}
 static List<string> Strings(ZipArchive z){var a=new List<string>();if(z.GetEntry("xl/sharedStrings.xml")==null)return a;foreach(XmlNode s in Read(z,"xl/sharedStrings.xml").DocumentElement.ChildNodes)a.Add(Text(s));return a;}
 static object Value(XmlElement c,List<string> strings){string type=c.GetAttribute("t");if(type=="inlineStr")return Text(Child(c,"is"));var v=Child(c,"v");if(v==null)return null;switch(type){case "s":return strings[int.Parse(v.InnerText,Inv)];case "str":case "e":return v.InnerText;case "b":return v.InnerText=="1";default:double d;if(double.TryParse(v.InnerText,NumberStyles.Float,Inv,out d))return d;throw new InvalidDataException("Invalid XLSX number "+c.GetAttribute("r"));}}
 static int Col(string address){int n=0;foreach(char c in address){if(c<'A'||c>'Z')break;n=n*26+c-'A'+1;}return n;}
 static int Row(string a){int i=0;while(i<a.Length&&char.IsLetter(a[i]))i++;return int.Parse(a.Substring(i),Inv);}
 static string Address(int row,int col){string s="";while(col>0){col--;s=(char)('A'+col%26)+s;col/=26;}return s+row.ToString(Inv);}
 public static string Extract(string file){using(var z=ZipFile.OpenRead(file)){var sheet=Read(z,Sheets(z)[0]);var strings=Strings(z);var rows=new SortedDictionary<int,Dictionary<int,object>>();int maxCol=0;foreach(XmlElement c in Nodes(sheet,"//*[local-name()='sheetData']/*/*[local-name()='c']")){string a=c.GetAttribute("r");int r=Row(a),col=Col(a);Dictionary<int,object> values;if(!rows.TryGetValue(r,out values)){values=new Dictionary<int,object>();rows[r]=values;}values[col]=Value(c,strings);maxCol=Math.Max(maxCol,col);}int header=0;foreach(var r in rows){object v;if(r.Value.TryGetValue(1,out v)&&Convert.ToString(v)=="债券简称"){header=r.Key;break;}}if(header==0)throw new InvalidDataException("DM data header not found");var h=rows[header];while(maxCol>7&&(!h.ContainsKey(maxCol)||h[maxCol]==null))maxCol--;var headers=new object[maxCol];for(int j=1;j<=maxCol;j++)if(h.ContainsKey(j))headers[j-1]=h[j];var data=new List<object>();foreach(var r in rows){if(r.Key<=header||!r.Value.ContainsKey(1)||r.Value[1]==null||!r.Value.ContainsKey(2)||r.Value[2]==null)continue;var values=new object[maxCol];for(int j=1;j<=maxCol;j++)if(r.Value.ContainsKey(j))values[j-1]=r.Value[j];data.Add(new{row=r.Key,name=values[0],type=values[1],coupon=values[6],values=values});}object title=null;if(rows.ContainsKey(2)&&rows[2].ContainsKey(1))title=rows[2][1];return Json().Serialize(new{title=Convert.ToString(title,Inv),headerRow=header,headers=headers,rows=data});}}
 sealed class Grid {
  public XmlDocument Doc;XmlElement data;Dictionary<string,XmlElement> cells=new Dictionary<string,XmlElement>();SortedDictionary<int,XmlElement> rows=new SortedDictionary<int,XmlElement>();
  public Grid(XmlDocument d){Doc=d;data=Child(d.DocumentElement,"sheetData");if(data==null)throw new InvalidDataException("Missing sheetData");foreach(XmlElement r in data.ChildNodes){rows[int.Parse(r.GetAttribute("r"),Inv)]=r;foreach(XmlElement c in r.ChildNodes)if(c.LocalName=="c")cells[c.GetAttribute("r")]=c;}}
  public XmlElement Cell(string a){XmlElement c;if(cells.TryGetValue(a,out c))return c;int n=Row(a);XmlElement r;if(!rows.TryGetValue(n,out r)){r=Doc.CreateElement("row",Ns);r.SetAttribute("r",n.ToString(Inv));data.AppendChild(r);rows[n]=r;}c=Doc.CreateElement("c",Ns);c.SetAttribute("r",a);r.AppendChild(c);cells[a]=c;return c;}
  public void Set(string a,object v,bool formula){var c=Cell(a);while(c.HasChildNodes)c.RemoveChild(c.FirstChild);c.RemoveAttribute("t");if(v==null||(v is string&&(string)v==""))return;if(formula){Add(c,"f").InnerText=Convert.ToString(v,Inv).TrimStart('=');return;}if(v is string){c.SetAttribute("t","inlineStr");var t=Add(Add(c,"is"),"t");t.SetAttribute("space","http://www.w3.org/XML/1998/namespace","preserve");t.InnerText=Encode((string)v);}else if(v is bool){c.SetAttribute("t","b");Add(c,"v").InnerText=(bool)v?"1":"0";}else{double d=Convert.ToDouble(v,Inv);if(double.IsNaN(d)||double.IsInfinity(d))throw new InvalidDataException("Nonfinite cell number");Add(c,"v").InnerText=d.ToString("R",Inv);}}
  public void Block(int first,object[] values){for(int i=0;i<values.Length;i++){var row=(object[])values[i];for(int j=0;j<row.Length;j++)Set(Address(first+i,j+1),row[j],false);}}
  public void Forms(object[] forms){foreach(Dictionary<string,object> f in forms)Set((string)f["cell"],f["value"],true);}
  public void Finish(){int maxRow=1,maxCol=1;foreach(var pair in rows){var r=pair.Value;var list=new List<XmlElement>();foreach(XmlElement c in r.ChildNodes)if(c.LocalName=="c")list.Add(c);list.Sort((a,b)=>Col(a.GetAttribute("r")).CompareTo(Col(b.GetAttribute("r"))));foreach(var c in list){r.AppendChild(c);maxCol=Math.Max(maxCol,Col(c.GetAttribute("r")));}data.AppendChild(r);maxRow=Math.Max(maxRow,pair.Key);}var dim=Child(Doc.DocumentElement,"dimension");if(dim!=null)dim.SetAttribute("ref","A1:"+Address(maxRow,maxCol));}
 }
 static void Copy(string source,string output){if(Path.GetFullPath(source)==Path.GetFullPath(output))throw new InvalidOperationException("XLSX output must differ from source");File.Copy(source,output,false);}
 public static void Upload(string source,string input,string output){Copy(source,output);using(var z=ZipFile.Open(output,ZipArchiveMode.Update)){var sheets=Sheets(z);if(sheets.Count!=5)throw new InvalidDataException("Unexpected DQ official template layout");for(int k=1;k<5;k++){var g=new Grid(Read(z,sheets[k]));for(int r=2;r<=101;r++)for(int c=1;c<=10;c++)g.Set(Address(r,c),null,false);if(k==1)g.Block(2,(object[])Json().DeserializeObject(File.ReadAllText(input,Encoding.UTF8)));g.Finish();Save(z,sheets[k],g.Doc);}}}
 static XmlElement NamedFont(XmlElement original,string name){var f=(XmlElement)original.CloneNode(true);var n=Child(f,"name");if(n==null)n=Add(f,"name");n.SetAttribute("val",name);var scheme=Child(f,"scheme");if(scheme!=null)f.RemoveChild(scheme);return f;}
 static bool Cjk(char c){return c>127;}
 static void Fonts(ZipArchive z,List<Grid> grids){var styles=Read(z,"xl/styles.xml");var fonts=Child(styles.DocumentElement,"fonts");var xfs=Child(styles.DocumentElement,"cellXfs");int count=xfs.ChildNodes.Count;var map=new int[count,2];for(int i=0;i<count;i++){var xf=(XmlElement)xfs.ChildNodes[i];int fontId=int.Parse(xf.GetAttribute("fontId"),Inv);for(int k=0;k<2;k++){int id=fonts.ChildNodes.Count;fonts.AppendChild(NamedFont((XmlElement)fonts.ChildNodes[fontId],k==0?"Times New Roman":"楷体"));var clone=(XmlElement)xf.CloneNode(true);clone.SetAttribute("fontId",id.ToString(Inv));clone.SetAttribute("applyFont","1");map[i,k]=xfs.ChildNodes.Count;xfs.AppendChild(clone);}}fonts.SetAttribute("count",fonts.ChildNodes.Count.ToString(Inv));xfs.SetAttribute("count",xfs.ChildNodes.Count.ToString(Inv));var strings=Strings(z);foreach(var grid in grids)foreach(XmlElement cell in Nodes(grid.Doc,"//*[local-name()='sheetData']/*/*[local-name()='c']")){int style=cell.HasAttribute("s")?int.Parse(cell.GetAttribute("s"),Inv):0;object value=Value(cell,strings);string text=Child(cell,"f")==null?value as string:null;bool chinese=text!=null&&Array.Exists(text.ToCharArray(),Cjk);cell.SetAttribute("s",map[style,chinese?1:0].ToString(Inv));if(!chinese)continue; // Mixed text uses run fonts; other style properties continue to inherit from the cell.
    while(cell.HasChildNodes)cell.RemoveChild(cell.FirstChild);cell.SetAttribute("t","inlineStr");var inline=Add(cell,"is");int start=0;for(int i=1;i<=text.Length;i++){if(i<text.Length&&Cjk(text[i])==Cjk(text[start]))continue;var run=Add(inline,"r");Add(Add(run,"rPr"),"rFont").SetAttribute("val",Cjk(text[start])?"楷体":"Times New Roman");var t=Add(run,"t");t.SetAttribute("space","http://www.w3.org/XML/1998/namespace","preserve");t.InnerText=Encode(text.Substring(start,i-start));start=i;}}
   Save(z,"xl/styles.xml",styles);
 }
 public static void PrepareReport(string source,string planFile,string output){Copy(source,output);var p=(Dictionary<string,object>)Json().DeserializeObject(File.ReadAllText(planFile,Encoding.UTF8));using(var z=ZipFile.Open(output,ZipArchiveMode.Update)){var names=Sheets(z);if(names.Count!=5)throw new InvalidDataException("Report requires five sheets");var grids=new List<Grid>();foreach(string n in names)grids.Add(new Grid(Read(z,n)));grids[1].Block(2,(object[])p["samples"]);grids[1].Set("D1",((object[])((Dictionary<string,object>)p["headers"])["samples"])[3],false);grids[2].Block(2,(object[])p["dq"]);var dqRows=(object[])p["dq"];for(int i=0;i<dqRows.Length;i++)grids[2].Set("L"+(i+2),DateValue(((object[])dqRows[i])[11]),false);grids[3].Block(1,new object[]{p["dmHeaders"]});grids[3].Block(2,(object[])p["dm"]);grids[4].Block(2,(object[])p["history"]);grids[0].Set("B3",DateValue(p["date"]),false);grids[0].Set("A19",p["reportText"],false);if(p.ContainsKey("scoringNote"))grids[0].Set("A17",p["scoringNote"],false);var forms=(Dictionary<string,object>)p["forms"];grids[0].Forms((object[])forms["summary"]);grids[1].Forms((object[])forms["samples"]);grids[2].Forms((object[])forms["dq"]);Fonts(z,grids);for(int i=0;i<5;i++){grids[i].Finish();Save(z,names[i],grids[i].Doc);}var b=Read(z,"xl/workbook.xml");var calc=Child(b.DocumentElement,"calcPr");if(calc==null)calc=Add(b.DocumentElement,"calcPr");calc.SetAttribute("calcMode","auto");calc.SetAttribute("fullCalcOnLoad","1");calc.SetAttribute("forceFullCalc","1");Save(z,"xl/workbook.xml",b); // Cached values must be calculated by the selected Office engine.
    if(z.GetEntry("xl/calcChain.xml")!=null){z.GetEntry("xl/calcChain.xml").Delete();var rels=Read(z,"xl/_rels/workbook.xml.rels");foreach(XmlNode n in Nodes(rels,"//*[contains(@Type,'/calcChain')]"))n.ParentNode.RemoveChild(n);Save(z,"xl/_rels/workbook.xml.rels",rels);var types=Read(z,"[Content_Types].xml");foreach(XmlNode n in Nodes(types,"//*[@PartName='/xl/calcChain.xml']"))n.ParentNode.RemoveChild(n);Save(z,"[Content_Types].xml",types);}
 }}
}
